import {test} from 'node:test';import assert from 'node:assert/strict';import {playerAuthorization} from '../../AG WORLD/server/player-auth.js';
async function run({method='POST',path='/farms',header='',valid=true,enrolled=true}={}){let called=false,queries=0;const req={method,path,headers:{'x-actor-id':'forged'},get:n=>n==='authorization'?header:undefined};const res={statusCode:200,status(n){this.statusCode=n;return this},json(data){this.data=data;return this}};await playerAuthorization({query:async()=>{queries++;return {rows:enrolled?[{id:'player-a'}]:[]}}},async()=>({ok:valid,json:async()=>({id:'player-a'})}))(req,res,()=>{called=true});return {req,res,called,queries};}
test('anonymous writes and production test endpoint are denied',async()=>{assert.equal((await run()).res.statusCode,401);assert.equal((await run({path:'/v2/relationships/acceptance-test'})).res.statusCode,404);assert.equal((await run({method:'GET',path:'/health'})).called,true);});
test('valid enrolled players carry server-verified audit identity',async()=>{const r=await run({header:'Bearer fixture'});assert.equal(r.called,true);assert.equal(r.req.headers['x-actor-id'],'player-a');assert.equal((await run({header:'Bearer fixture',valid:false})).queries,0);assert.equal((await run({header:'Bearer fixture',enrolled:false})).res.statusCode,403);});
test('private profile reads are limited to the verified player',async()=>{assert.equal((await run({method:'GET',path:'/users/player-b/profile',header:'Bearer fixture'})).res.statusCode,403);assert.equal((await run({method:'GET',path:'/users/player-a/profile',header:'Bearer fixture'})).called,true);});
